const foundation=[
{title:'沈黙のはじまり',place:'はじまりの村',topic:'LINK / 物理・リンク層',pos:[180,310],story:'村の通信灯が消えた。案内人リンクによると、旅人の端末と中継器をつなぐインターフェースが停止しているらしい。まずは足元の接続を調べよう。',goals:['eth0 のリンク状態を UP にする','中継器 192.168.10.1 へ ping を通す'],hint:'まず ip link で確認。ip link set eth0 up はインターフェースを有効にする操作。その後 ping 192.168.10.1 で到達性を確認しよう。',note:'コンピュータネットワークの階層モデルでは、物理層・データリンク層が通信の土台。ここではケーブルは接続済みで、管理上停止したインターフェースを扱う。リンクが UP でも、IP の設定が正しいとは限らない。',lore:'interface は「間にある面」。異なるもの同士が接する境界を表す言葉。',init:{link:false,ip:'192.168.10.20/24',gateway:null,dns:null,firewall:false}},
{title:'住所を失った街',place:'アドレスの街',topic:'IPv4 / サブネット',pos:[330,220],story:'街の端末に誤った住所が配られていた。中継器は 192.168.10.1/24。この街で指定された未使用アドレス 192.168.10.20/24 を設定して、同じネットワークに戻そう。',goals:['eth0 に 192.168.10.20/24 を設定','192.168.10.1 へ ping を通す'],hint:'ip addr で現在の住所を調べよう。この演習では ip addr replace 192.168.10.20/24 dev eth0 で住所を置換できる。/24 は先頭24ビットがネットワーク部という意味。',note:'IPv4 は32ビットのアドレス。/24 はネットワーク部が24ビットで、残り8ビットがホスト部。同じ /24 の 192.168.10.20 と 192.168.10.1 は、ルーターを越えずに通信できる。',lore:'subnet は sub（下位）＋ network。大きなネットワークを小さく分けたもの。',init:{link:true,ip:'192.168.99.20/24',gateway:null,dns:null,firewall:false}},
{title:'国境のゲートウェイ',place:'境界の関所',topic:'ROUTING / 経路制御',pos:[490,160],story:'村の中では通信できるのに、遠くの書庫へ届かない。ルーター 192.168.10.1 を外への出口に設定し、遠隔サーバー 10.20.0.80 への道を開こう。',goals:['デフォルト経路を 192.168.10.1 に設定','10.20.0.80 へ ping を通す'],hint:'ip route で経路表を表示。ip route add default via 192.168.10.1 は、より具体的な経路がない宛先をこのルーターへ送る設定。',note:'ネットワーク層では、宛先IPと経路表から次の転送先を選ぶ。デフォルトゲートウェイは万能な代理人ではなく、具体的な経路がない場合の次の転送先。この世界では中継ルーターの先と戻り経路は設定済み。',lore:'gateway は文字通り「門への道」。default route は 0.0.0.0/0 とも書く。',init:{link:true,ip:'192.168.10.20/24',gateway:null,dns:null,firewall:false}},
{title:'名前を忘れた書庫',place:'DNS の書庫',topic:'DNS / 名前解決',pos:[650,240],story:'IPアドレスなら届くのに、archive.net の名では書庫を見つけられない。DNSサーバー 192.168.10.53 を設定して、名前と住所を結び直そう。',goals:['DNS を 192.168.10.53 に設定','dig archive.net で名前を解決','ping archive.net で到達を確認'],hint:'sudo resolvectl dns eth0 192.168.10.53 でDNSサーバーを設定。dig archive.net は問い合わせ結果の確認、ping archive.net は名前解決後の通信確認。',note:'DNS はアプリケーション層の仕組みで、名前からIPアドレスなどの情報を得る。名前解決の成功と、相手への通信の成功は別。IPへの ping が通り名前で失敗するなら、DNSを切り分ける手掛かりになる。',lore:'DNS は Domain Name System。dig は Domain Information Groper に由来する調査コマンド。',init:{link:true,ip:'192.168.10.20/24',gateway:'192.168.10.1',dns:null,firewall:false}},
{title:'閉ざされた城門',place:'フィルター城',topic:'TCP / ファイアウォール',pos:[730,350],story:'書庫には到達するのに、Webの扉だけが開かない。端末の送信フィルターが TCP 443 を遮断している。必要な通信を許可し、HTTPSで書庫を開こう。',goals:['TCP 443 の送信を許可する','curl https://archive.net を成功させる'],hint:'sudo iptables -S OUTPUT で規則を確認。sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT でHTTPSの通信を許可し、curl https://archive.net を実行。iptables の -I OUTPUT は送信ルールの先頭に規則を挿入する。',note:'ping が使うICMPと、HTTPSが通常使うTCPは異なる。ping が成功してもWebを利用できるとは限らない。実環境ではポートに加え、方向・宛先・接続状態なども規則で指定する。',lore:'firewall は建物の「防火壁」に由来する。延焼を防ぐ壁のように通信の通過を制御する。',init:{link:true,ip:'192.168.10.20/24',gateway:'192.168.10.1',dns:'192.168.10.53',firewall:true}},
{title:'最後の灯台',place:'接続の灯台',topic:'FINAL / 総合障害調査',pos:[460,365],story:'最後の灯台には、複数の障害が残されている。リンクから順番に観測し、原因を切り分けよう。書庫の復興信号を取得できれば、すべての街に灯りが戻る。',goals:['リンク・IP・経路・DNS・TCP 443 を復旧','curl https://archive.net で復興信号を取得'],hint:'ip link → ip addr → ip route → resolvectl status eth0 → sudo iptables -S OUTPUT。下の層から一つずつ確認し、既知の正常値へ直そう。各地と同じネットワーク構成だ。',note:'障害調査は観測→仮説→変更→再確認の反復。複数の原因をまとめて推測せず、どこまで正常かを狭める。実際にはパケットキャプチャやサーバーのログも組み合わせる。',lore:'ping の名はソナーの反響音から。応答がない理由は切断だけでなく、ICMPの遮断などもある。',init:{link:false,ip:'192.168.99.20/24',gateway:null,dns:null,firewall:true}}
];

import {initial,network,ready} from './engine.mjs';
const normal={};
const extra=[
{title:'偽りの隣人',place:'ARP の森',topic:'ARP / 近隣解決',story:'森の管理人マックが、交換した中継器に通信できず困っている。IPは正しい。しかし端末には古い固定MACが残っていた。近隣表を調べ、正しい相手を見つけ直そう。',goals:['ip neigh で誤った固定エントリーを観測','近隣表を消去し、中継器へ ping'],hint:'ip neigh → sudo ip neigh del 192.168.10.1 dev eth0 → ping 192.168.10.1。del は指定したゲートウェイの近隣エントリーだけを削除する。',note:'ARPは同一リンク上でIPv4に対応するMACアドレスを求める。遠隔の宛先へ送るときに調べるのは、遠隔ホストではなく次ホップのルーターのMAC。IPv6ではARPではなく近隣探索を用いる。',lore:'ARP は Address Resolution Protocol。ここでの resolution は解像度ではなく「解決」を意味する。',init:{arpBad:true},checks:[(s,e)=>e['arp-inspected'],(s,e)=>!s.arpBad&&e['ping:192.168.10.1']&&!network(s,'192.168.10.1').error],solution:['ip neigh','sudo ip neigh del 192.168.10.1 dev eth0','ping 192.168.10.1'],why:'IPが正しくても、LAN上でフレームを届ける相手が誤っていると通信できない。',tools:['ip neigh','sudo ip neigh del 192.168.10.1 dev eth0','ping 192.168.10.1']},
{title:'住所配りの郵便局',place:'DHCP 郵便局',topic:'DHCP / 自動設定',story:'新しい端末をつなぐたびに、住所を手で書くのは大変だ。配達員リースから、DHCPでIP・出口・DNSをまとめて受け取ってほしいと依頼された。',goals:['DHCPでアドレスの貸与を受ける','archive.net のWebを取得する'],hint:'sudo dhclient -v eth0 でDORAの流れを観測。ip addr / ip route / resolvectl status eth0 で配布内容を確認し、curl https://archive.net。',note:'DHCPはIPv4アドレスだけでなくサブネットマスク・ルーター・DNSなども配布する。新規取得の典型はDiscover、Offer、Request、ACKの4段階。実際の更新では常に4段階すべてを行うわけではない。',lore:'DHCP は Dynamic Host Configuration Protocol。lease は「貸与」。アドレスは永久に所有するものではなく、期限を持って借りる。',init:{ip:null,gateway:null,dns:null},checks:[s=>s.lease,(s,e)=>ready(s)&&e.curl],solution:['sudo dhclient -v eth0','curl https://archive.net'],why:'設定が一度に変わる理由を、配布されたオプションとして理解しよう。',tools:['sudo dhclient -v eth0','ip addr','ip route','resolvectl status eth0']},
{title:'広すぎた国境',place:'マスクの峡谷',topic:'CIDR / サブネット計算',story:'端末は 192.168.10.20/16、実際のLANは 192.168.10.0/24。192.168.20.80 はルーターの先にある隣国だ。広すぎる境界を直し、隣国へ使者を送ろう。',goals:['ipcalc でネットワーク範囲を計算','端末を 192.168.10.20/24 に修正','192.168.20.80 へ ping を通す'],hint:'ipcalc 192.168.10.20/16 で範囲を確認。ip route get 192.168.20.80 の結果を修正前後で比べよう。ip addr replace 192.168.10.20/24 dev eth0。',note:'同一サブネットかどうかは見た目の住所の近さでなく、IPとマスクのビット演算で決まる。/16では192.168.20.80まで直接接続と見なしARPする。/24に直すとデフォルト経路でルーターへ送る。',lore:'CIDR は Classless Inter-Domain Routing。「クラス」に固定されず、/24や/27などの長さでネットワークを表す。',init:{ip:'192.168.10.20/16'},checks:[(s,e)=>e.subnet,s=>s.ip==='192.168.10.20/24',(s,e)=>e['ping:192.168.20.80']&&!network(s,'192.168.20.80').error],solution:['ipcalc 192.168.10.20/16','ip addr replace 192.168.10.20/24 dev eth0','ping 192.168.20.80'],why:'「同じLANにいる」という端末の判断が誤っている。ゲートウェイが設定済みでも使われない。',tools:['ipcalc 192.168.10.20/16','ip route get 192.168.20.80','ip addr']},
{title:'近道という罠',place:'分岐の砦',topic:'LPM / 最長一致',story:'書庫へのデフォルト経路は正しいのに通信できない。古い工事用の 10.20.0.0/24 via 192.168.10.254 が残っていた。経路表から実際に選ばれる道を見抜こう。',goals:['ip route get で選択された経路を確認','誤った /24 経路を削除','書庫 10.20.0.80 へ ping'],hint:'ip route get 10.20.0.80 → ip route del 10.20.0.0/24 → ping 10.20.0.80。デフォルト経路の追加だけでは /24 に勝てない。',note:'ルーティングでは宛先に一致する経路のうち最もプレフィックスが長いものを優先する。/24は/0より具体的なので、デフォルトが正常でも誤った/24へ送られる。本演習はメトリックやポリシールーティングを省略している。',lore:'Longest Prefix Match（最長プレフィックス一致）は、ルーターの高速な検索アルゴリズムにも直結する考え方。',init:{routes:[{prefix:'10.20.0.0/24',via:'192.168.10.254'}]},checks:[(s,e)=>e['route-inspected'],s=>!s.routes.some(r=>r.prefix==='10.20.0.0/24'),(s,e)=>e['ping:10.20.0.80']&&!network(s,'10.20.0.80').error],solution:['ip route get 10.20.0.80','ip route del 10.20.0.0/24','ping 10.20.0.80'],why:'「経路があるか」と「どの経路が選ばれるか」は別の問い。',tools:['ip route','ip route get 10.20.0.80','ip route del 10.20.0.0/24']},
{title:'昨日の住所録',place:'記憶の書庫',topic:'CACHE / DNSキャッシュ',story:'司書レコードは書庫を移転した。dig では新住所なのに、curl は旧住所 10.20.0.99 へ向かってしまう。端末に残る古い記憶を調べよう。',goals:['dig archive.net でDNSの正しい応答を観測','resolvectl show-cache で端末側の古い記録を確認','キャッシュを消しHTTPSで接続'],hint:'dig archive.net と resolvectl show-cache を比較。sudo resolvectl flush-caches でローカルキャッシュを削除し、curl https://archive.net。',note:'この演習ではdigはDNSサーバーへ直接問い合わせ、curlやpingは端末の名前解決キャッシュを使う。DNSサーバーの応答が正常でも、アプリやOSのキャッシュが古い場合がある。実環境では各層のTTLとキャッシュ機構を調べる。',lore:'cache はフランス語の「隠し場所」に由来する。頻繁に使う情報を近くに置くが、鮮度管理が必要。',init:{cache:'10.20.0.99'},checks:[(s,e)=>e['dig:archive.net'],(s,e)=>e['cache-inspected'],(s,e)=>!s.cache&&ready(s)&&e.curl],solution:['dig archive.net','resolvectl show-cache','sudo resolvectl flush-caches','curl https://archive.net'],why:'同じ「名前解決」でも、どこへ問い合わせた結果なのかを区別する。',tools:['dig archive.net','resolvectl show-cache','sudo resolvectl flush-caches']},
{title:'短命な使者',place:'TTL の峠',topic:'TTL / ホップ制限',story:'峠を越える使者が、最初のルーターで消えてしまう。送信TTLを1にした通信と、通常の通信を比較し、通る道を調べよう。設定を壊す必要はない。',goals:['ping -t 1 で TTL 超過を観測','traceroute で経路を観測','通常の ping で書庫へ到達'],hint:'ping -t 1 10.20.0.80 → traceroute 10.20.0.80 → ping 10.20.0.80。失敗を観測すること自体が最初の条件。',note:'IPv4のTTLは転送時に減らされ、0になったパケットは破棄される。無限ループを防ぐための仕組み。tracerouteはTTLを段階的に増やしたプローブへの応答から経路を推定する。途中の無応答は必ずしも転送停止を意味しない。',lore:'TTL は Time To Live。名前は「生存時間」だが、実際のIP転送では主にホップ数の上限として働く。DNSのTTLはキャッシュの有効時間で、用途が異なる。',init:normal,checks:[(s,e)=>e['ttl-expired'],(s,e)=>e.trace,(s,e)=>e['ping:10.20.0.80']&&!network(s,'10.20.0.80').error],solution:['ping -t 1 10.20.0.80','traceroute 10.20.0.80','ping 10.20.0.80'],why:'障害ではなく、プローブに設定した制約が原因の失敗もある。',tools:['ping -t 1 10.20.0.80','traceroute 10.20.0.80','ping 10.20.0.80']},
{title:'扉の向こうは無人',place:'待受の港',topic:'TCP / サービス',story:'港の番人は「pingは返るのにWebが開かない」と言う。フィルターは許可済み。管理権限を預かった書庫サーバーのHTTPSサービスを調べ、停止していれば起動しよう。',goals:['nc で Connection refused を観測','書庫サーバーのサービス状態を確認','HTTPSを起動して curl で取得'],hint:'nc -vz archive.net 443 → service status → service start https → curl https://archive.net。service は管理対象サーバーを操作するゲーム用コマンド。',note:'TCPの接続拒否とタイムアウトは異なる手掛かり。待受がないホストはRSTで拒否することがあり、破棄するフィルターではタイムアウトになる。本演習は原因を固定しているが、実環境ではREJECT規則などでも拒否が起こる。',lore:'port は「港」。IPがホストへの住所なら、ポート番号はそのホスト上の通信の入口を区別する。',init:{service:false},checks:[(s,e)=>e['port-refused:443'],(s,e)=>e['service-inspected'],(s,e)=>s.service&&ready(s)&&e.curl],solution:['nc -vz archive.net 443','service status','service start https','curl https://archive.net'],why:'ネットワークが正常でも、接続を受けるプログラムが起動していなければ利用できない。',tools:['nc -vz archive.net 443','service status','service start https']},
{title:'届いた、けれど見つからない',place:'HTTP の広場',topic:'HTTP / アプリケーション層',story:'広場の掲示板に古いURL /old が残っている。正しい稼働確認用パスは /health。404応答を観測し、それが「通信できなかった」とは違うことを確かめよう。',goals:['curl で /old の404応答を観測','/health の200応答を取得'],hint:'curl https://archive.net/old → curl https://archive.net/health。HTTP応答が返ったなら、ここではDNS・TCP・TLSを通過している。',note:'HTTPのステータスコードはアプリケーション層の応答。404は要求した資源が見つからないことを示し、ネットワーク障害と同一ではない。実際にはプロキシやCDNが応答する場合もあり、どのサーバーの応答かにも注意する。',lore:'HTTP は Hypertext Transfer Protocol。URLのパスは、同じサーバー内の資源を指定する部分。',init:normal,checks:[(s,e)=>e.http404,(s,e)=>e.health&&ready(s)],solution:['curl https://archive.net/old','curl https://archive.net/health'],why:'失敗メッセージを一括りにせず、どの層が何を返したかを読む。',tools:['curl https://archive.net/old','curl https://archive.net/health']},
{title:'必要な扉だけを',place:'防壁の要塞',topic:'POLICY / 最小権限',story:'守備隊長フィルターは、復旧を急ぐあまり全開放することを禁じた。業務に必要なHTTPS 443は許可し、不要なTelnet 23は拒否する方針を実装しよう。',goals:['sudo iptables -S OUTPUT で現在の方針を確認','送信TCP 443を許可しTCP 23を拒否','HTTPS取得とTCP 23の遮断を検証'],hint:'sudo iptables -S OUTPUT → sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT → sudo iptables -I OUTPUT -p tcp --dport 23 -j DROP → curl https://archive.net → nc -vz archive.net 23。規則の存在だけでなく通信も確かめよう。',note:'最小権限の原則は、目的に必要な範囲の権限だけを与える設計。今回はポート別の送信規則だけだが、実際は宛先・方向・状態・規則の順序も重要。Telnetは暗号化されないため、管理には通常SSHなどを使う。',lore:'Telnetの標準ポートは23、HTTPSは443。ポート番号だけで実際のアプリケーションを完全に識別できるわけではない。',init:{firewall:true},checks:[(s,e)=>e['fw-inspected'],s=>!s.firewall&&s.blocked.includes(23),(s,e)=>ready(s)&&e.curl&&e['port-filtered:23']],solution:['sudo iptables -S OUTPUT','sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT','sudo iptables -I OUTPUT -p tcp --dport 23 -j DROP','curl https://archive.net','nc -vz archive.net 23'],why:'使えることと、不要な通信が通らないことの両方を検証する。',tools:['sudo iptables -S OUTPUT','sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT','sudo iptables -I OUTPUT -p tcp --dport 23 -j DROP','nc -vz archive.net 23']},
{title:'二重の迷い道',place:'霧の回廊',topic:'INCIDENT / 複合障害',story:'復旧班はDNSの値を直したが、まだWebが開かない。書庫の新住所は10.20.0.80、正しい出口は192.168.10.1。名前と経路をそれぞれ観測し、二つの古い設定を取り除こう。',goals:['DNSキャッシュと選択経路を調査','正しい経路と最新の名前解決でHTTPSを取得'],hint:'resolvectl show-cache と ip route get 10.20.0.80 を確認。sudo resolvectl flush-caches と ip route del 10.20.0.0/24 の両方が必要。最後に curl https://archive.net。',note:'複合障害では一つの修正が成功しても、全体は復旧しないことがある。変更後の症状の変化は失敗ではなく、次の層に進んだ手掛かり。設定を一つずつ変更すると因果関係を追いやすい。',lore:'incident は運用上のサービス中断や品質低下などの事象。原因を調べる際は、影響と復旧の確認も重要。',init:{cache:'10.20.0.99',routes:[{prefix:'10.20.0.0/24',via:'192.168.10.254'}]},checks:[(s,e)=>e['cache-inspected']&&e['route-inspected'],(s,e)=>ready(s)&&!s.cache&&e.curl],solution:['resolvectl show-cache','ip route get 10.20.0.80','sudo resolvectl flush-caches','ip route del 10.20.0.0/24','curl https://archive.net'],why:'名前の問題を直した後、経路の問題が見えてくる。観測を繰り返そう。',tools:['resolvectl show-cache','dig archive.net','ip route get 10.20.0.80']},
{title:'嵐のあとの通信網',place:'嵐の前哨地',topic:'RECOVERY / 多層復旧',story:'嵐のあと、リンク、住所、近隣表、サービスに障害が残った。端末はDHCP対応。管理するサーバーまで段階的に復旧し、/healthから稼働信号を取得しよう。',goals:['DHCPで端末設定を再取得','近隣表・送信規則・HTTPSサービスを復旧','/health の稼働信号を取得'],hint:'ip link set eth0 up → sudo dhclient -v eth0 → sudo ip neigh del 192.168.10.1 dev eth0 → sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT → service start https → curl https://archive.net/health。各変更の前に対応する状態表示を試そう。',note:'階層を下から調べるのは有用な出発点だが、常に唯一の最短手順ではない。直前の変更や影響範囲、既知の正常端末との比較から、より有力な仮説を立てられる。',lore:'runbook は運用の作業手順書。コマンドだけでなく、実施条件・期待結果・戻し方を書くと再現性が高まる。',init:{link:false,ip:null,gateway:null,dns:null,arpBad:true,firewall:true,service:false},checks:[s=>s.lease,s=>!s.arpBad&&!s.firewall&&s.service,(s,e)=>ready(s)&&e.health],solution:['ip link set eth0 up','sudo dhclient -v eth0','sudo ip neigh del 192.168.10.1 dev eth0','sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT','service start https','curl https://archive.net/health'],why:'一つの成功だけで復旧と判断せず、利用者が必要な機能まで確認する。',tools:['ip link','ip addr','ip neigh','sudo iptables -S OUTPUT','service status']},
{title:'ネットワーカーの証',place:'暁の中枢',topic:'CAPSTONE / 最終実践',story:'最後の任務だ。正しい設計は192.168.10.20/24、出口192.168.10.1、DNS192.168.10.53。HTTPSだけを使えるようにし、不要なTCP 23は閉じる。残された複数の障害を観測で特定し、稼働信号を取り戻そう。',goals:['経路・DNSキャッシュ・サービスの状態を観測','正しいIP設定と必要最小限の送信規則を実現','/health の200応答を取得'],hint:'ip route get 10.20.0.80 / resolvectl show-cache / service status で調査。/24への修正、古い静的経路とキャッシュの削除、HTTPS起動、443許可・23拒否を進めよう。',note:'調査の完了は「エラーが消えた」だけでなく、目的の機能と安全な通信方針が成立したことを確認する段階。ログを残せば、次の担当者が観測と変更の根拠を追える。',lore:'capstone は建造物の頂部を仕上げる石。学習した内容を統合する最終課題にも使われる。',init:{ip:'192.168.10.20/16',routes:[{prefix:'10.20.0.0/24',via:'192.168.10.254'}],cache:'10.20.0.99',service:false,firewall:true},checks:[(s,e)=>e['route-inspected']&&e['cache-inspected']&&e['service-inspected'],s=>s.ip==='192.168.10.20/24'&&!s.firewall&&s.blocked.includes(23),(s,e)=>ready(s)&&e.health],solution:['ip route get 10.20.0.80','resolvectl show-cache','service status','ip addr replace 192.168.10.20/24 dev eth0','ip route del 10.20.0.0/24','sudo resolvectl flush-caches','service start https','sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT','sudo iptables -I OUTPUT -p tcp --dport 23 -j DROP','curl https://archive.net/health'],why:'観測から原因を特定し、変更の効果を利用者の視点で検証できれば一人前。',tools:['ip route get 10.20.0.80','resolvectl show-cache','service status','sudo iptables -S OUTPUT']}
];
const solutions=[['ip link set eth0 up','ping 192.168.10.1'],['ip addr replace 192.168.10.20/24 dev eth0','ping 192.168.10.1'],['ip route add default via 192.168.10.1','ping 10.20.0.80'],['sudo resolvectl dns eth0 192.168.10.53','dig archive.net','ping archive.net'],['sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT','curl https://archive.net'],['ip link set eth0 up','ip addr replace 192.168.10.20/24 dev eth0','ip route add default via 192.168.10.1','sudo resolvectl dns eth0 192.168.10.53','sudo iptables -I OUTPUT -p tcp --dport 443 -j ACCEPT','curl https://archive.net']];
const baseChecks=[
[s=>s.link,(s,e)=>e['ping:192.168.10.1']&&!network(s,'192.168.10.1').error],
[s=>s.ip==='192.168.10.20/24',(s,e)=>e['ping:192.168.10.1']&&!network(s,'192.168.10.1').error],
[s=>s.gateway==='192.168.10.1',(s,e)=>e['ping:10.20.0.80']&&!network(s,'10.20.0.80').error],
[s=>s.dns==='192.168.10.53',(s,e)=>e['dig:archive.net'],(s,e)=>e['ping:archive.net']&&!network(s,'10.20.0.80').error],
[s=>!s.firewall,(s,e)=>ready(s)&&e.curl],
[s=>ready(s),(s,e)=>ready(s)&&e.curl]
];
export const CHAPTERS=[{title:'接続の旅路',subtitle:'基礎 / 6 QUESTS',map:'断線の大陸',badge:'接続の旅人'},{title:'見えない仕組み',subtitle:'探索 / 6 QUESTS',map:'霧深き群島',badge:'経路の探究者'},{title:'復旧の技法',subtitle:'実践 / 6 QUESTS',map:'暁の大陸',badge:'ネットワーク守護者'}];
export const QUESTS=[...foundation.map((q,i)=>({...q,checks:baseChecks[i],solution:solutions[i],tools:['ip link','ip addr','ip route',...solutions[i].slice(-2)],why:q.note.split('。')[0]+'。'})),...extra].map((q,i)=>({...q,id:i,chapter:Math.floor(i/6),xp:i<6?150:i<12?200:300,init:initial(q.init),pos:foundation[i%6].pos,brief:i<6?'まず状態を読み、変更後の通信を確かめよう。':q.why}));
QUESTS[5].story='最初の大陸をつなぐ灯台には、複数の障害が残されている。リンクから順番に観測し、原因を切り分けよう。書庫の復興信号を取得すると、霧の向こうの第2章が開かれる。';
export function goalResults(q,state,evidence){return q.checks.map(fn=>Boolean(fn(state,evidence)))}
export function createLab(){const faults=[['link',false],['ip','192.168.99.20/24'],['gateway',null],['dns',null],['arpBad',true],['cache','10.20.0.99'],['firewall',true],['service',false],['routes',[{prefix:'10.20.0.0/24',via:'192.168.10.254'}]]];for(let i=faults.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[faults[i],faults[j]]=[faults[j],faults[i]]}const selected=faults.slice(0,3);return initial(Object.fromEntries(selected))}
